window.GR_TRANSCRICAO = {"codigo":"d1-cidades-cerrado","titulo":"As Cidades do Cerrado: ciência para entender o que muda debaixo dos nossos pés e sobre nossas cabeças","dia":"Dia 1 · 25 nov 2026","hora":"9h30–10h40","locutores":[{"nome":"Pedro Novaes","falas":14},{"nome":"Ary Soares dos Santos","falas":90},{"nome":"Carlos Gurjão","falas":171},{"nome":"Celene Cunha","falas":145},{"nome":"João Batista de Deus","falas":110}],"segmentos":[{"t":"00:00:01","s":"Pedro Novaes","x":"Obrigado, Guilherme."},{"t":"00:00:02","s":"Pedro Novaes","x":"Obrigado, Wendel."},{"t":"00:00:03","s":"Pedro Novaes","x":"Obrigado, Zilma."},{"t":"00:00:04","s":"Pedro Novaes","x":"Obrigado, Bochecha."},{"t":"00:00:05","s":"Pedro Novaes","x":"Fique à vontade."},{"t":"00:00:07","s":"Pedro Novaes","x":"Vou já, então, chamar aqui o Ary Soares dos Santos, que é diretor executivo do IDESA, mas, mais que isso, uma figura que está, apesar de ser muito jovem,"},{"t":"00:00:19","s":"Pedro Novaes","x":"está há muito tempo nesse debate socioambiental, já tendo passado por muitas funções em muitos lugares."},{"t":"00:00:30","s":"Pedro Novaes","x":"E ele vai, então, coordenar esse primeiro painel, que é o As Cidades do Cerrado, Ciência para Entender o que Muda Debaixo dos Nossos Pés e Sobre Nossas Cabeças."},{"t":"00:00:44","s":"Pedro Novaes","x":"Aqui a gente vai ouvir de um lado um pouco do que a ciência nos diz hoje sobre como o clima está mudando no Cerrado e, de outro, ouvir também como, do ponto de vista do planejamento urbano e da gestão urbana, a gente deve responder a isso."},{"t":"00:01:01","s":"Pedro Novaes","x":"Com você."},{"t":"00:01:05","s":"Pedro Novaes","x":"Se quiser eu vou pegar os nomes daqui, mas se quiser eu pego o roteiro aqui."},{"t":"00:01:27","s":"Ary Soares dos Santos","x":"Bom dia a todos, bom dia a todas."},{"t":"00:01:31","s":"Ary Soares dos Santos","x":"Em especial, reiterando aqui, hoje, este 25 de novembro, esta pauta tão fundamental, não só para os dias de hoje, mas especialmente dos últimos anos, em relação às mulheres."},{"t":"00:01:46","s":"Ary Soares dos Santos","x":"E, especialmente, com a profusão"},{"t":"00:01:51","s":"Ary Soares dos Santos","x":"do que a gente tem hoje das tais redes sociais, de como vocês mulheres têm sido vítimas preferenciais daqueles que não sabem lidar com o contraditório, daqueles que não sabem reconhecer o protagonismo que vocês mulheres têm tido em todas as áreas do conhecimento,"},{"t":"00:02:15","s":"Ary Soares dos Santos","x":"em todas as áreas das relações públicas, especialmente das relações humanas."},{"t":"00:02:22","s":"Ary Soares dos Santos","x":"E faço aqui uma menção toda especial à mamãe que está aí com o seu bebê, que eu perdi."},{"t":"00:02:29","s":"Ary Soares dos Santos","x":"É a Mari, a nossa assessora de comunicação."},{"t":"00:02:32","s":"Ary Soares dos Santos","x":"Pois é."},{"t":"00:02:33","s":"Ary Soares dos Santos","x":"já torturando a nenenzinha dela com esse tipo de debate."},{"t":"00:02:41","s":"Ary Soares dos Santos","x":"Ela, com certeza, vai crescer com isso já na gênese dela e vai ser uma pessoa que muito vai contribuir com a gente."},{"t":"00:02:50","s":"Ary Soares dos Santos","x":"Bom, muito me honra mais uma vez estar aqui com vocês."},{"t":"00:02:55","s":"Ary Soares dos Santos","x":"O Goiânia Resiliente, desde a sua primeira edição, ele já mostrou a que veio, tem contribuído muito para esta..."},{"t":"00:03:08","s":"Ary Soares dos Santos","x":"a relação entre o saber científico, entre a academia e as políticas públicas tem contribuído de forma muito efetiva para que a gente avance, para que a gente não fique só naquele discurso quase árido que a academia acaba tendo que fazer."},{"t":"00:03:31","s":"Ary Soares dos Santos","x":"Eu sou oriundo também da UFG, professor, onde eu tive oportunidade tanto da graduação quanto do mestrado"},{"t":"00:03:38","s":"Ary Soares dos Santos","x":"na área de geografia, e muito me honra estar aqui entre pares."},{"t":"00:03:44","s":"Ary Soares dos Santos","x":"E, neste sentido, já para que a gente avance nos trabalhos, eu gostaria de chamar aqui para a mesa o professor Carlos Gurjão."},{"t":"00:04:01","s":"Ary Soares dos Santos","x":"O professor Carlos Gurjão é um dos coordenadores do CEMPA-Cerrado."},{"t":"00:04:07","s":"Ary Soares dos Santos","x":"da Universidade Federal de Goiás."},{"t":"00:04:09","s":"Ary Soares dos Santos","x":"E vou dar oportunidade aqui, professor, para que o senhor apresente-se melhor daqui a pouco."},{"t":"00:04:16","s":"Ary Soares dos Santos","x":"E, para debater com o professor, que vai nos fazer aqui uma explanação sobre essas questões climáticas de forma mais aprofundada, uma vez que ele é um climatologista, é um pesquisador que vem lidando com esse tema já há algum tempo."},{"t":"00:04:35","s":"Ary Soares dos Santos","x":"eu convido aqui a professora Celene Cunha, que vai ser uma das nossas debatedoras, professora Celene Cunha, que é lá da Universidade Federal de Goiás, também uma das minhas maiores incentivadoras, especialmente quando no mestrado contribuiu muito"},{"t":"00:04:59","s":"Ary Soares dos Santos","x":"para que eu, de certa forma, escolhesse a área que eu acabei estudando."},{"t":"00:05:05","s":"Ary Soares dos Santos","x":"E a professora Celene não conhece só das questões das grandes cidades do Brasil."},{"t":"00:05:11","s":"Ary Soares dos Santos","x":"Ela tem participado de fóruns mundo afora."},{"t":"00:05:15","s":"Ary Soares dos Santos","x":"Alguns anos atrás, eu tive, professora, lá no IGOT,"},{"t":"00:05:19","s":"Ary Soares dos Santos","x":"que é a universidade lá de Lisboa."},{"t":"00:05:21","s":"Ary Soares dos Santos","x":"E a professora Eduarda, ou Maria Eduarda, salvo engano, logo de cara perguntou, você é lá de Goiás, você conhece a professora Celene?"},{"t":"00:05:29","s":"Ary Soares dos Santos","x":"Então, sim, é uma professora que se relaciona com a ciência mundo afora."},{"t":"00:05:36","s":"Ary Soares dos Santos","x":"E o professor João de Deus, nosso outro debatedor."},{"t":"00:05:41","s":"Ary Soares dos Santos","x":"João de Deus, que eu tive a oportunidade de conhecer em Catalão, lá nos hitos dos anos..."},{"t":"00:05:49","s":"Ary Soares dos Santos","x":"88, 89, o João de Deus era aluno já da última fase do curso de Geografia e eu estava iniciando lá a graduação."},{"t":"00:06:01","s":"Ary Soares dos Santos","x":"Bom, o objetivo nosso aqui, quem vai fazer as exposições melhores são eles, eu estou apenas com a missão árdua de controlar tempos e propiciar depois a interação"},{"t":"00:06:17","s":"Ary Soares dos Santos","x":"de eventuais perguntas de vocês."},{"t":"00:06:18","s":"Ary Soares dos Santos","x":"Isto, se a gente tiver o tempo que o relógio nos permitir."},{"t":"00:06:25","s":"Ary Soares dos Santos","x":"Mas vamos lá."},{"t":"00:06:26","s":"Ary Soares dos Santos","x":"Professor, tenha bondade, faça a sua explanação."},{"t":"00:06:31","s":"Ary Soares dos Santos","x":"Já me orientaram aqui a questão de tempo."},{"t":"00:06:34","s":"Ary Soares dos Santos","x":"Salvo engano, o senhor tem 25 minutos para a sua exposição."},{"t":"00:06:37","s":"Ary Soares dos Santos","x":"A professora Celene, salvo engano, uns 15 minutos para também contribuir."},{"t":"00:06:44","s":"Ary Soares dos Santos","x":"E logo em seguida, o professor João de Deus."},{"t":"00:06:46","s":"Ary Soares dos Santos","x":"Fique à vontade e da melhor maneira que o senhor preferir."},{"t":"00:06:52","s":"Carlos Gurjão","x":"Olá, bom dia a todos e a todas."},{"t":"00:06:56","s":"Carlos Gurjão","x":"Eu fico muito lisonjeado de estar aqui debatendo hoje com vocês, principalmente porque trata-se de um tema muito importante, que é o Goiânia resiliente, porque esse Goiânia resiliente não reflete apenas para a gente, mas reflete também para outras cidades do Cerrado, bem como também do Brasil."},{"t":"00:07:15","s":"Carlos Gurjão","x":"E gostaria também de cumprimentar os organizadores do Goiânia Resiliente e também aqui presentes docentes, pesquisadores, gestores públicos, estudantes e todos aqueles que se preocupam com uma cidade sustentável e uma cidade também de futuro que nos espera daqui para frente."},{"t":"00:07:47","s":"Carlos Gurjão","x":"Quando se trata de mudanças climáticas,"},{"t":"00:07:50","s":"Carlos Gurjão","x":"ao mesmo tempo a gente já pensa no sentido de escala global."},{"t":"00:07:54","s":"Carlos Gurjão","x":"Na escala global, quando trata-se de aumento da temperatura média do planeta, uma variabilidade na distribuição das chuvas em vários pontos do globo."},{"t":"00:08:10","s":"Carlos Gurjão","x":"Mas nós esquecemos também de uma parte muito importante que pode estar a nosso alcance, que é justamente uma microescala."},{"t":"00:08:19","s":"Carlos Gurjão","x":"que pode ser essa em que estamos lidando com as nossas circulações em vias urbanas, as nossas circulações no nosso próprio setor que moramos, bem como também nas próprias vias em que sentimos um conforto térmico."},{"t":"00:08:40","s":"Carlos Gurjão","x":"Então, quando se trata de mudanças climáticas, a gente não deve apenas olhar a atmosfera, não só podemos analisar a atmosfera, devemos também verificar qual o impacto que isso vai trazer para um setor"},{"t":"00:08:55","s":"Carlos Gurjão","x":"no setor urbano, visto esse que o setor urbano tanto poderá gerar modificações no seu próprio solo, modificações essas que passam de solo vegetado para um solo concretado, asfaltado."},{"t":"00:09:10","s":"Carlos Gurjão","x":"E, dentre outras situações, bem como também qualidade do ar,"},{"t":"00:09:15","s":"Carlos Gurjão","x":"o aumento de doenças, como, por exemplo, a dengue, bem como também outros fatores."},{"t":"00:09:23","s":"Carlos Gurjão","x":"Aqui, eu gostaria de trazer para vocês, trouxe alguns slides e também resultados para nós compreendermos e também debatermos sobre todas as situações e vocês terem a oportunidade"},{"t":"00:09:37","s":"Carlos Gurjão","x":"de também nos perguntar, me perguntar de toda essa situação."},{"t":"00:09:42","s":"Carlos Gurjão","x":"E parte de uma cidade é parte também de um sistema climático."},{"t":"00:09:48","s":"Carlos Gurjão","x":"E esse sistema climático tem, por exemplo, o ciclo da água."},{"t":"00:09:53","s":"Carlos Gurjão","x":"O ciclo da água não acaba se tornando apenas em volta de um ambiente, um paisagismo em grande escala."},{"t":"00:10:01","s":"Carlos Gurjão","x":"Ele também acaba sendo modificado em um setor da micro escala, ou seja, num setor urbano, principalmente em setores que exigem uma melhor atenção, principalmente em questões de metrópoles, como é o caso de Goiânia."},{"t":"00:10:17","s":"Carlos Gurjão","x":"Então, por toda essa situação, quando existe uma modificação no próprio ambiente, como a modificação do solo passando de vegetação para concreto, de concreto para asfalto, existe uma própria variabilidade"},{"t":"00:10:33","s":"Carlos Gurjão","x":"variabilidade nas condições térmicas, no balanço de energia, assim como também na modificação da concentração de umidade."},{"t":"00:10:43","s":"Carlos Gurjão","x":"E isso gera um próprio impacto nas próprias chuvas que ocorrem em uma cidade, visto isso também que eu deixo claro que a gente vem observando nos últimos anos eventos extremos."},{"t":"00:10:55","s":"Carlos Gurjão","x":"Então,"},{"t":"00:10:56","s":"Carlos Gurjão","x":"Fica aqui uma reflexão."},{"t":"00:10:59","s":"Carlos Gurjão","x":"Será que as nossas cidades estão realmente preparadas para lidar com eventos extremos, meteorológicos, bem como também climáticos, visto que nós já estamos vivenciando isso?"},{"t":"00:11:11","s":"Carlos Gurjão","x":"Então, eu gero aqui essa reflexão, essa pergunta, para saber se realmente nós estamos preparados para tal."},{"t":"00:11:19","s":"Carlos Gurjão","x":"Uma cidade, como ela é parte do sistema climático, também está em..."},{"t":"00:11:25","s":"Carlos Gurjão","x":"exposição a essas situações que requerem uma maior atenção, principalmente a pessoas que vivem em questões de vulnerabilidade social."},{"t":"00:11:35","s":"Carlos Gurjão","x":"Por quê?"},{"t":"00:11:36","s":"Carlos Gurjão","x":"Nós, quando analisamos uma cidade, principalmente estamos apenas observando realmente"},{"t":"00:11:44","s":"Carlos Gurjão","x":"Os gestores públicos estão lidando com a situação de melhoramento de um sistema de drenagem, melhoramento de um sistema de paisagismo urbano, mas acabam esquecendo de toda a parte de infraestrutura, bem como também das suas próprias decisões."},{"t":"00:12:00","s":"Carlos Gurjão","x":"Decisões essas que acabam impactando em toda a população, sejam essas."},{"t":"00:12:05","s":"Carlos Gurjão","x":"desde planejamento urbano até tomada de decisões com uma questão voltada tanto para a parte de comunicação, bem como também para a parte de ações que envolvem tanto a ciência, bem como também gerando até a defesa civil."},{"t":"00:12:22","s":"Carlos Gurjão","x":"Então, por tudo isso, acaba gerando uma parte de ciclo."},{"t":"00:12:28","s":"Carlos Gurjão","x":"Aqui eu trago também outra situação importante, é que as chuvas torrenciais continuam ocorrendo."},{"t":"00:12:35","s":"Carlos Gurjão","x":"E a gente vem percebendo isso ao longo dos anos."},{"t":"00:12:39","s":"Carlos Gurjão","x":"Ao longo dos anos esses que, nas últimas décadas, a gente vem apresentando um aumento de eventos extremos,"},{"t":"00:12:46","s":"Carlos Gurjão","x":"E, quando eu falo de eventos extremos climáticos, eu estou associando a chuvas torrenciais, essas chuvas que estão associadas a grandes volumes de água em um curto período de tempo, bem como também chuvas ocasionais, ou seja, uma chuva que é mal distribuída em uma cidade."},{"t":"00:13:07","s":"Carlos Gurjão","x":"Isso quer dizer o seguinte, que chove demais em um determinado setor e acaba não chovendo quase nada"},{"t":"00:13:13","s":"Carlos Gurjão","x":"em outros setores deste mesmo município."},{"t":"00:13:17","s":"Carlos Gurjão","x":"E aqui eu trago como exemplo o Rio Meia Ponte, que transborda."},{"t":"00:13:20","s":"Carlos Gurjão","x":"Isso é uma notícia de 2020."},{"t":"00:13:23","s":"Carlos Gurjão","x":"Então, eu preciso pegar um pouco do passado para a gente compreender e trazer até para o período contemporâneo o que a gente pode, o que a gente melhorou até o momento."},{"t":"00:13:34","s":"Carlos Gurjão","x":"Então, as chuvas torrenciais apresentam uma tendência de aumento nas grandes regiões urbanas, nos setores urbanos."},{"t":"00:13:42","s":"Carlos Gurjão","x":"devido a um mau planejamento dessa questão de drenagem, de infiltração no solo, uma vez que o solo se encontra impermeável, ele acaba gerando um aumento do escoamento superficial, devido a essas chuvas."},{"t":"00:13:58","s":"Carlos Gurjão","x":"Então, não é apenas a própria chuva de grande intensidade, é apenas também uma questão de infraestrutura, uma questão de planejamento daquele município."},{"t":"00:14:11","s":"Carlos Gurjão","x":"Aqui nós temos também uma situação que foi o que ocorreu no último sábado, no dia 21."},{"t":"00:14:20","s":"Carlos Gurjão","x":"Como eu vou repetir e enfatizar sobre essa questão das chuvas torrenciais, isso aqui é um caso muito sério que ocorreu aqui na cidade, porque em um intervalo de duas horas choveu 70 milímetros em alguns pontos da cidade."},{"t":"00:14:37","s":"Carlos Gurjão","x":"70 milímetros..."},{"t":"00:14:39","s":"Carlos Gurjão","x":"e acaba variando entre 65 e 60."},{"t":"00:14:42","s":"Carlos Gurjão","x":"E vejam que a chuva acaba sendo mal distribuída em todo o município, mas 70 milímetros acaba sendo um grande volume de água em um curto período de tempo."},{"t":"00:14:55","s":"Carlos Gurjão","x":"E o que acontece quando existe uma falta de planejamento?"},{"t":"00:14:59","s":"Carlos Gurjão","x":"Uma falta de planejamento que eu quero dizer quando existe uma própria mudança naquele solo, quando você acaba de diminuir a sua permeabilidade."},{"t":"00:15:11","s":"Carlos Gurjão","x":"Acaba gerando o que a gente considera como um aumento desse escoamento que, consequentemente, gera alagamentos."},{"t":"00:15:18","s":"Carlos Gurjão","x":"Alagamentos esses que geram também transtornos e impactos à sociedade,"},{"t":"00:15:23","s":"Carlos Gurjão","x":"como também impactos sociais e econômicos."},{"t":"00:15:31","s":"Carlos Gurjão","x":"Isso acaba nos gerando um grande alerta, porque a outra imagem que vocês observam aqui, que é uma imagem associada a um véu de noiva, como vocês podem ver, que a gente considera como chuva convectiva."},{"t":"00:15:46","s":"Carlos Gurjão","x":"As chuvas convectivas nas cidades ocorrem com grande frequência, principalmente nesse período de estação chuvosa."},{"t":"00:15:54","s":"Carlos Gurjão","x":"Então, dificilmente a gente consegue prever o local exato em que vai cair essa chuva."},{"t":"00:16:00","s":"Carlos Gurjão","x":"A gente sabe que está com uma condição favorável à ocorrência de chuva, mas nós ainda não sabemos pontualmente onde vai ocorrer."},{"t":"00:16:10","s":"Carlos Gurjão","x":"E essas chuvas acabam sendo mais corriqueiras ano a ano, e o que a gente vem observando também."},{"t":"00:16:16","s":"Carlos Gurjão","x":"Então, tem outra situação, aquilo que a gente pode enfatizar novamente, toda essa questão das modificações no solo, como, por exemplo, a diminuição daquela área verde, daquela área vegetada, com a impermeabilização."},{"t":"00:16:35","s":"Carlos Gurjão","x":"Isso gera alguns fatores, como, por exemplo, impactos, como, por exemplo, no impacto no balanço de energia."},{"t":"00:16:42","s":"Carlos Gurjão","x":"Por quê?"},{"t":"00:16:43","s":"Carlos Gurjão","x":"Porque em um solo vegetado..."},{"t":"00:16:45","s":"Carlos Gurjão","x":"ele acaba ponderando toda essa situação da temperatura."},{"t":"00:16:51","s":"Carlos Gurjão","x":"Então, ele acaba absorvendo parte dessa temperatura e diminuindo, assim, a sua reemissão para o ar que está ali próximo da superfície."},{"t":"00:16:59","s":"Carlos Gurjão","x":"Em contrapartida, o próprio solo, um solo concretado e asfaltado, ele acaba armazenando parte daquela energia que é incidente sobre ele"},{"t":"00:17:09","s":"Carlos Gurjão","x":"sendo que ele emite com maior facilidade para a atmosfera."},{"t":"00:17:13","s":"Carlos Gurjão","x":"E isso acaba gerando aquele desconforto, aquele aumento de temperatura ao longo do dia."},{"t":"00:17:18","s":"Carlos Gurjão","x":"E esse aumento acaba gerando feedbacks positivos para uma tendência de aumento de temperatura ao longo do tempo."},{"t":"00:17:25","s":"Carlos Gurjão","x":"Então, outra situação também a que, mais uma vez, eu posso enfatizar é toda essa questão da falta de drenagem, desse planejamento que a gente pode perceber quando existe uma grande descarga d'água, uma vez que a chuva em si"},{"t":"00:17:45","s":"Carlos Gurjão","x":"a mesma chuva que ocorre em vários setores acaba sendo mal distribuída nessas regiões, como por exemplo essa questão da drenagem urbana."},{"t":"00:17:56","s":"Carlos Gurjão","x":"Uma vez que, em regiões em que a população vive em situações vulneráveis,"},{"t":"00:18:02","s":"Carlos Gurjão","x":"Não existe um planejamento urbano tão adequado comparado com setores onde vivem pessoas de alto poder aquisitivo."},{"t":"00:18:12","s":"Carlos Gurjão","x":"Então, é totalmente diferente a climatologia."},{"t":"00:18:16","s":"Carlos Gurjão","x":"E, quando eu falo em climatologia, eu não estou me considerando apenas com a demanda atmosférica."},{"t":"00:18:21","s":"Carlos Gurjão","x":"Eu levo em consideração o impacto ambiental que aquilo também vai nos trazer."},{"t":"00:18:27","s":"Carlos Gurjão","x":"Outra situação importante nessa questão de, sendo as mesmas chuvas, as mesmas consequências, então a gente deve lembrar que Goiás está em um estado que fica em transição, em transição em relação às chuvas, aos fenômenos meteorológicos."},{"t":"00:18:46","s":"Carlos Gurjão","x":"Mas a nossa chuva aqui apresenta uma variabilidade sazonal muito bem definida."},{"t":"00:18:52","s":"Carlos Gurjão","x":"Isso quer dizer o seguinte, um período de chuva, um período que a gente considera como período monçônico, que faz parte do período monçônico da América do Sul, em que tem seis meses de chuva e seis meses sem chuva."},{"t":"00:19:05","s":"Carlos Gurjão","x":"Isso quer dizer o seguinte, a gente tem chuva durante..."},{"t":"00:19:08","s":"Carlos Gurjão","x":"esses meses, que é de outubro a abril, e um período de estiagem que é de maio a meados de setembro."},{"t":"00:19:18","s":"Carlos Gurjão","x":"Então, durante esse período de chuva, a gente também vem observando uma má distribuição dessas chuvas, principalmente em zonas urbanas e em torno dessas regiões, uma vez que"},{"t":"00:19:34","s":"Carlos Gurjão","x":"Quando existe uma modificação no paisagismo local, acaba interferindo também no microclima local."},{"t":"00:19:43","s":"Carlos Gurjão","x":"E isso gera consequências."},{"t":"00:19:46","s":"Carlos Gurjão","x":"Quando existe essa modificação urbana, acaba gerando o quê?"},{"t":"00:19:51","s":"Carlos Gurjão","x":"Em alguns pontos ou regiões, aquela região acaba tendo um feedback positivo para a seca."},{"t":"00:19:57","s":"Carlos Gurjão","x":"Isso quer dizer o seguinte, com vários dias consecutivos de estiagem, aquela zona que tinha uma determinada vegetação, ou passou agora a ser uma vegetação de pastagem, ela se torna um pouco mais vulnerável à ocorrência de queimadas."},{"t":"00:20:14","s":"Carlos Gurjão","x":"Então, aqui a gente pega também um gancho de uma situação."},{"t":"00:20:17","s":"Carlos Gurjão","x":"Nós estamos passando por um período de El Niño."},{"t":"00:20:21","s":"Carlos Gurjão","x":"El Niño é um fenômeno natural, um fenômeno que faz parte da variabilidade climática."},{"t":"00:20:26","s":"Carlos Gurjão","x":"Ele ocorre há milhões de anos e tem sua periodicidade de três a sete anos."},{"t":"00:20:32","s":"Carlos Gurjão","x":"E, por uma situação que a gente já vem analisando, e mesmo pelas predições, que já faz um ano que a gente já vinha trabalhando, porque os próprios modelos de previsão já vinham prevendo que nós teríamos um El Niño, e um El Niño que ele estava com intensidade moderada, forte ou muito forte, a gente já vinha se preparando em comunicação com os gestores públicos."},{"t":"00:20:58","s":"Carlos Gurjão","x":"Então, aqui a gente tem como exemplo"},{"t":"00:21:01","s":"Carlos Gurjão","x":"um El Niño de 2015 com um El Niño de 2013 a 2014."},{"t":"00:21:08","s":"Carlos Gurjão","x":"Então, a gente faz uma comparação em que sempre que a gente passa por anos de El Niño, acaba gerando consequências."},{"t":"00:21:19","s":"Carlos Gurjão","x":"Por quê?"},{"t":"00:21:20","s":"Carlos Gurjão","x":"A gente já pode observar esse ano no Brasil que tanto o Nordeste quanto o Sul do Brasil apresentam uma polaridade em relação às chuvas."},{"t":"00:21:28","s":"Carlos Gurjão","x":"Enquanto o sul apresenta excesso de chuvas, o nordeste já começa a apresentar uma redução dessas chuvas."},{"t":"00:21:34","s":"Carlos Gurjão","x":"Parte também da região amazônica."},{"t":"00:21:36","s":"Carlos Gurjão","x":"Aqui na região centro-oeste, ela acaba tendo uma má distribuição dessas chuvas, mas apresenta também um aumento das temperaturas."},{"t":"00:21:45","s":"Carlos Gurjão","x":"Eu preciso deixar claro também que"},{"t":"00:21:49","s":"Carlos Gurjão","x":"ele traz essas consequências, a gente não pode levar em consideração apenas as consequências de queimadas."},{"t":"00:21:55","s":"Carlos Gurjão","x":"Porque, quando eu falo de queimadas, eu estou falando de aumento da poluição do ar."},{"t":"00:22:01","s":"Carlos Gurjão","x":"E a poluição do ar está associada também com a sua qualidade do ar nessa zona urbana."},{"t":"00:22:09","s":"Carlos Gurjão","x":"E vem interferindo em outras situações."},{"t":"00:22:11","s":"Carlos Gurjão","x":"Por quê?"},{"t":"00:22:12","s":"Carlos Gurjão","x":"Quando falo em queimadas, não estou apenas falando em queimadas em todo o entorno da cidade."},{"t":"00:22:18","s":"Carlos Gurjão","x":"Estou falando em queimadas mesmo na região amazônica."},{"t":"00:22:23","s":"Carlos Gurjão","x":"Ela pode ser transportada para essa região urbana que passa aqui."},{"t":"00:22:28","s":"Carlos Gurjão","x":"por Goiânia, uma vez que existe um fenômeno que a gente considera que é um canal de umidade, também conhecido como rios atmosféricos, que acaba transportando parte dessa umidade para essas regiões urbanas ou estados estratégicos em que passa esse rio atmosférico."},{"t":"00:22:44","s":"Carlos Gurjão","x":"e ele acaba trazendo parte dessa fuligem, parte dessas micropartículas para nós e acaba piorando a qualidade do ar na região."},{"t":"00:22:54","s":"Carlos Gurjão","x":"Bem como também as próprias queimadas que ocorrem em torno da zona urbana acabam piorando a qualidade do ar."},{"t":"00:23:01","s":"Carlos Gurjão","x":"Aí é onde entra uma situação."},{"t":"00:23:03","s":"Carlos Gurjão","x":"Para que exista uma formação de uma nuvem, é necessário ter um componente, um determinado componente."},{"t":"00:23:11","s":"Carlos Gurjão","x":"E o componente padrão é o NaCl, que é o cloreto de sódio."},{"t":"00:23:14","s":"Carlos Gurjão","x":"Então, ele faz com que exista um crescimento das gotículas de nuvem e faz aumentar a nuvem e seu desenvolvimento."},{"t":"00:23:22","s":"Carlos Gurjão","x":"Mas, no momento em que nós temos um aumento de poluição atmosférica,"},{"t":"00:23:28","s":"Carlos Gurjão","x":"acaba gerando uma diminuição, ou seja, uma redução dessas nuvens de chuva."},{"t":"00:23:33","s":"Carlos Gurjão","x":"Então, o clima local acaba sendo modificado com a quantificação, com o aumento dessas micropartículas."},{"t":"00:23:42","s":"Carlos Gurjão","x":"Isso gera, com o passar do tempo, um feedback"},{"t":"00:23:47","s":"Carlos Gurjão","x":"positivo para a seca."},{"t":"00:23:48","s":"Carlos Gurjão","x":"Às vezes pode ser um pouco complexo, mas é fácil da gente compreender quando existe uma modificação do paisagismo, seja ele urbano, bem como o entorno, que ele acaba gerando esse feedback, uma vez que a evapotranspiração ou a evaporação da superfície acaba diminuindo."},{"t":"00:24:10","s":"Carlos Gurjão","x":"Outra questão importante é que"},{"t":"00:24:13","s":"Carlos Gurjão","x":"Pegando ainda o gancho de El Niño, a gente deve compreender que a saúde a gente também deve levar em consideração, uma vez que a própria Fiocruz fez uma projeção, fez um estudo recentemente que saiu, e que com esse ano de El Niño muito forte, de categoria muito forte, a projeção é que até abril de 2027 sejam registrados 866 mil casos de dengue."},{"t":"00:24:41","s":"Carlos Gurjão","x":"bem como também 90 mil casos de chikungunya, devido a essa questão da atuação do El Niño."},{"t":"00:24:47","s":"Carlos Gurjão","x":"Por quê?"},{"t":"00:24:47","s":"Carlos Gurjão","x":"Porque existe uma má distribuição das chuvas."},{"t":"00:24:50","s":"Carlos Gurjão","x":"O El Niño não é que ele cause essa má distribuição, mas ele também, como nós estamos tendo um aumento de eventos extremos ao longo dos últimos anos, o El Niño acaba potencializando..."},{"t":"00:25:03","s":"Carlos Gurjão","x":"O quê?"},{"t":"00:25:04","s":"Carlos Gurjão","x":"A redução das chuvas, ou seja, o aumento de estiagens, que, consequentemente, gera o quê?"},{"t":"00:25:10","s":"Carlos Gurjão","x":"Aumento de estiagens, diminuição das chuvas, bem como também as ondas de calor."},{"t":"00:25:15","s":"Carlos Gurjão","x":"Então, as ondas de calor tendem a aumentar frequentemente durante esse período."},{"t":"00:25:19","s":"Carlos Gurjão","x":"Aqui são os resultados."},{"t":"00:25:22","s":"Carlos Gurjão","x":"Eu achei interessante ter sido convidado aqui para esse debate do Goiânia Resiliente."},{"t":"00:25:30","s":"Carlos Gurjão","x":"E eu gostaria de mostrar para vocês que,"},{"t":"00:25:33","s":"Carlos Gurjão","x":"Eu, como meteorologista, climatologista e pesquisador, me sinto lisonjeado aqui debatendo isso com vocês, porque eu posso trazer aqui alguns resultados que a gente já vem tratando e já vem divulgando, principalmente com a Secretaria de Ciência e Tecnologia do Estado de Goiás."},{"t":"00:25:51","s":"Carlos Gurjão","x":"E a gente já vem observando que, se vocês observarem onde está..."},{"t":"00:25:57","s":"Carlos Gurjão","x":"Goiânia está aqui, nessa região, nesse ponto, e aqui, Distrito Federal, com as cidades satélites da Brasília."},{"t":"00:26:04","s":"Carlos Gurjão","x":"E aqui a gente vem observando que existe um aumento de dias frequentes com temperaturas acima de 38 graus."},{"t":"00:26:13","s":"Carlos Gurjão","x":"Esse aumento de temperatura está justamente associado também ao aumento de ondas de calor que a gente vem observando nos últimos tempos."},{"t":"00:26:23","s":"Carlos Gurjão","x":"Outro fator importante, que aqui eu deixo claro, a gente nunca leva em consideração essa temperatura mínima."},{"t":"00:26:29","s":"Carlos Gurjão","x":"A gente sempre leva em consideração a temperatura média."},{"t":"00:26:31","s":"Carlos Gurjão","x":"A temperatura mínima mais baixa e a temperatura mínima máxima, a gente também observa nos últimos anos..."},{"t":"00:26:38","s":"Carlos Gurjão","x":"um aumento significativo, seja no verão, no outono, no inverno e na primavera."},{"t":"00:26:47","s":"Carlos Gurjão","x":"E vocês possam observar que todos esses casos aqui são de uma base de dados ou por meio de sensoriamento remoto."},{"t":"00:26:56","s":"Carlos Gurjão","x":"E faço questão de mostrar, porque não é apenas a cidade, todo o estado está sendo impactado por esse aumento de temperatura."},{"t":"00:27:04","s":"Carlos Gurjão","x":"Isso quer dizer o seguinte, as noites estão sendo mais quentes,"},{"t":"00:27:08","s":"Carlos Gurjão","x":"do que os anos anteriores."},{"t":"00:27:10","s":"Carlos Gurjão","x":"Então, nos últimos anos, isso aqui é uma análise interdecadal, a gente começa a observar tudo isso."},{"t":"00:27:16","s":"Carlos Gurjão","x":"Outra questão importante que a gente já vem tendo observado também corriqueiramente são eventos extremos através de tempestades severas, que vem aumentando a cada vez mais."},{"t":"00:27:27","s":"Carlos Gurjão","x":"Uma vez que..."},{"t":"00:27:29","s":"Carlos Gurjão","x":"Quando a gente analisa uma tempestade que acaba derrubando algumas infraestruturas, ela tanto pode estar associada a micro explosões, que é considerada como microbursts, bem como também os tornados."},{"t":"00:27:42","s":"Carlos Gurjão","x":"Então aqui existe uma diferença quando o próprio vento com grande impacto acaba gerando um impacto também divergentemente na superfície."},{"t":"00:27:52","s":"Carlos Gurjão","x":"Então isso acaba gerando transtornos de uma maneira destrutiva para a sociedade."},{"t":"00:27:58","s":"Carlos Gurjão","x":"Outra situação é a respeito da previsão e a decisão."},{"t":"00:28:04","s":"Carlos Gurjão","x":"Como a gente pode se preparar?"},{"t":"00:28:06","s":"Carlos Gurjão","x":"Uma das maneiras seria o aumento da vegetação, com mais arborização, um planejamento..."},{"t":"00:28:14","s":"Carlos Gurjão","x":"melhorado da própria drenagem urbana, uma drenagem urbana mais eficiente, áreas mais permeáveis no entorno da cidade, proteção das nascentes, ações precoces que antecipam os riscos e salvam vidas."},{"t":"00:28:34","s":"Carlos Gurjão","x":"bem como também uma maior comunicação com a prevenção de monitoramento e uma comunicação com a defesa civil e uma saúde justamente para o calor, uma vez que a sociedade que é mais atingida são pessoas idosas, pessoas enfermas e crianças, principalmente para lidar com o aumento de temperatura, uma vez que o desconforto térmico acaba gerando problemas de saúde, respiratórios, bem como também a nossa capacidade cognitiva para raciocínio."},{"t":"00:29:03","s":"Carlos Gurjão","x":"E aqui eu gostaria de deixar claro para vocês que, infelizmente, a gente ainda existe uma carência de um instrumento ou até mesmo uma ferramenta extremamente importante, que é de um radar meteorológico aqui no próprio Estado, bem como também que ele fosse, que ele abrangisse a região metropolitana de Goiânia."},{"t":"00:29:26","s":"Carlos Gurjão","x":"Um radar meteorológico ajuda a salvar vidas, uma vez que nós conseguimos tomar"},{"t":"00:29:31","s":"Carlos Gurjão","x":"tomar decisões com antecedência."},{"t":"00:29:34","s":"Carlos Gurjão","x":"E essa antecedência faz nós, pesquisadores, meteorologistas, comunicar com facilidade com a defesa civil e a própria defesa civil pode agir com maior rapidez."},{"t":"00:29:47","s":"Carlos Gurjão","x":"Então, gostaria de dizer que a meteorologia age para diagnosticar os fenômenos meteorológicos, já a climatologia analisa os padrões e tendência, e a ciência nos ajuda a transformar risco em previsão."},{"t":"00:30:04","s":"Carlos Gurjão","x":"E agradeço muito a vocês pela atenção e por eu também estar aqui."},{"t":"00:30:09","s":"Carlos Gurjão","x":"Gostaria de agradecer também ao Pedro Novaes pelo convite, sou muito grato."},{"t":"00:30:15","s":"Carlos Gurjão","x":"a todos vocês, organizadores."},{"t":"00:30:16","s":"Carlos Gurjão","x":"Gostaria de agradecer também a Secretaria de Ciência e Tecnologia e Inovação do Governo do Estado, a Márcia Lobo, que também está aqui presente, a Elisabeth, que é a diretora do INMET, daqui de Goiânia, e a todos vocês aqui presentes."},{"t":"00:30:31","s":"Carlos Gurjão","x":"Obrigado também."},{"t":"00:30:32","s":"Carlos Gurjão","x":"Até vocês, debatedores."},{"t":"00:30:37","s":"Ary Soares dos Santos","x":"Professor Carlos, muito obrigado."},{"t":"00:30:40","s":"Ary Soares dos Santos","x":"Só para ressaltar a importância do que vocês vêm produzindo de ciência e de conhecimento e de como o Goiânia Resiliente tem conseguido contribuir com o planejamento da cidade."},{"t":"00:30:54","s":"Ary Soares dos Santos","x":"O Goiânia Resiliente foi plenamente absorvido pela nova gestão de Goiânia."},{"t":"00:31:02","s":"Ary Soares dos Santos","x":"Ainda nem tinha tomado posse..."},{"t":"00:31:05","s":"Ary Soares dos Santos","x":"doutora Zilma, que esteve presente com a gente lá, assumiu o compromisso de internalizar o que a gente estava discutindo desde o nosso primeiro fórum e hoje a gente tem uma diretoria dentro da AMMA estabelecida para pensar como absorver o conhecimento que a academia propicia para trazer para a gestão pública."},{"t":"00:31:27","s":"Ary Soares dos Santos","x":"Então, a responsabilidade que nós aqui temos"},{"t":"00:31:31","s":"Ary Soares dos Santos","x":"em contribuir para as cidades sustentáveis, ela tem encontrado eco na gestão pública."},{"t":"00:31:37","s":"Ary Soares dos Santos","x":"E, por isso, a gente fica mais animado e se sente ainda mais responsáveis de continuar produzindo conhecimento e que esse conhecimento seja traduzido."},{"t":"00:31:47","s":"Ary Soares dos Santos","x":"Agradeço a exposição do senhor, que, de forma muito didática, trouxe uma coisa que eu, enquanto aluno, tinha muita dificuldade de compreender."},{"t":"00:31:57","s":"Ary Soares dos Santos","x":"que são esses mecanismos que levam a fazer as previsões de tempo."},{"t":"00:32:01","s":"Ary Soares dos Santos","x":"Os modelos matemáticos que nos propiciam a entender a interação do ambiente em si com as nossas necessidades cotidianas."},{"t":"00:32:12","s":"Ary Soares dos Santos","x":"E o senhor trouxe de forma mais didática para esse seleto público que a gente tem aqui hoje."},{"t":"00:32:17","s":"Ary Soares dos Santos","x":"Professora Celene, com a senhora, 15 minutos."},{"t":"00:32:22","s":"Ary Soares dos Santos","x":"Fique à vontade, onde que a senhora achar melhor."},{"t":"00:32:30","s":"Celene Cunha","x":"Bom dia a todos."},{"t":"00:32:32","s":"Celene Cunha","x":"Agradeço muito o convite da pessoa do Pedro Novaes, nosso ex-aluno no curso de Geografia da UFG, meu ex-petiano, o grupo de alunos que existe no sistema da UFG e das federais."},{"t":"00:32:53","s":"Celene Cunha","x":"Vou dizer de onde vou falar rapidamente."},{"t":"00:32:57","s":"Celene Cunha","x":"Sou professora já aposentada na UFG, mas continuo na ativa."},{"t":"00:33:02","s":"Celene Cunha","x":"Sou professora do Programa de Pós-Graduação em Geografia da UFG, que hoje é um programa de excelência, junto com o professor João de Deus, programa do qual o Ary é egresso."},{"t":"00:33:18","s":"Celene Cunha","x":"E eu vou falar também de uma experiência que me está sendo muito cara."},{"t":"00:33:26","s":"Celene Cunha","x":"Eu coordeno, em Goiânia, em nosso estado, o núcleo do Observatório das Metrópoles, que é uma grande rede de pesquisa nacional."},{"t":"00:33:37","s":"Celene Cunha","x":"que têm se debruçado sobre a compreensão das metrópoles e regiões metropolitanas e também, agora, até se estendendo para outras situações, como vocês vão observar."},{"t":"00:33:53","s":"Celene Cunha","x":"Eu fiz rapidamente uma exposição."},{"t":"00:33:58","s":"Celene Cunha","x":"Não era bem... Aqui."},{"t":"00:34:08","s":"Celene Cunha","x":"Bom, o professor fez uma exposição, muita coisa que a gente até aprendeu aqui, que eu não sabia como funciona."},{"t":"00:34:20","s":"Celene Cunha","x":"Eu não sou exatamente da área de climatologia, eu atuo mais na área de planejamento urbano."},{"t":"00:34:28","s":"Celene Cunha","x":"E como a cidade se comporta nesse cenário?"},{"t":"00:34:31","s":"Celene Cunha","x":"Então, rapidamente, elas são emissoras de CO2, demandam recursos, são geradoras de resíduos e elas alteram o uso do solo."},{"t":"00:34:41","s":"Celene Cunha","x":"A urbanização impacta sobremaneira esse processo."},{"t":"00:34:47","s":"Celene Cunha","x":"Aqui eu trago uma imagem..."},{"t":"00:34:51","s":"Celene Cunha","x":"demonstrando quais são as áreas aqui na cidade de Goiânia e na região metropolitana que contém as favelas e comunidades conforme o censo de 2022."},{"t":"00:35:05","s":"Celene Cunha","x":"A gente costuma olhar pouco para essa situação."},{"t":"00:35:10","s":"Celene Cunha","x":"E é exatamente desse ponto que eu quero falar, que esses eventos extremos e esses descompassos que se manifestam nas cidades atingem"},{"t":"00:35:25","s":"Celene Cunha","x":"toda a cidade, certamente, mas com maior impacto e com maior efeito essas populações mais vulneráveis."},{"t":"00:35:34","s":"Celene Cunha","x":"Então, é importante que a gente tenha esse olhar e essa compreensão dessas situações que a gente convive na região metropolitana de Goiânia."},{"t":"00:35:49","s":"Celene Cunha","x":"E, a partir dessa ideia, essa rede, o Observatório das Metrópoles, em parceria com o Ministério das Cidades, está desenvolvendo e aplicando no Brasil inteiro esse projeto chamado Adaptação, que é o planejamento urbano para um futuro sustentável."},{"t":"00:36:13","s":"Celene Cunha","x":"Isso é um esforço de incluir na..."},{"t":"00:36:19","s":"Celene Cunha","x":"na pauta urbana e como esses elementos, principalmente as estratégias da política urbana, podem ser utilizados, podem ser potencializados, como eles podem ser usados"},{"t":"00:36:36","s":"Celene Cunha","x":"nessa direção para mitigar esses efeitos nas cidades."},{"t":"00:36:41","s":"Celene Cunha","x":"É um projeto de extensão."},{"t":"00:36:44","s":"Celene Cunha","x":"Aqui na nossa UFG é um projeto de extensão, como em toda rede que faz parte, que contém essa rede."},{"t":"00:36:59","s":"Celene Cunha","x":"Aqui é só uma visão de todos os núcleos que estão atuando nesse projeto."},{"t":"00:37:05","s":"Celene Cunha","x":"22 núcleos no Brasil e estamos, então, nesse trabalho bem articulado, né?"},{"t":"00:37:13","s":"Celene Cunha","x":"Nós estamos, no momento, terminamos essa etapa 1, etapa 2 e etapa 3, e vamos partir para essa etapa da capacitação e, no final, os resultados que serão implementados."},{"t":"00:37:30","s":"Celene Cunha","x":"Aqui, rapidamente, o balanço das grandes ocorrências registradas em 2024 no Brasil."},{"t":"00:37:37","s":"Celene Cunha","x":"O que a gente percebe é que está a nossa..."},{"t":"00:37:43","s":"Celene Cunha","x":"nossa situação, digamos assim, no contexto do Brasil."},{"t":"00:37:49","s":"Celene Cunha","x":"Os municípios que contêm as principais áreas de risco, no Brasil também."},{"t":"00:37:57","s":"Celene Cunha","x":"E aqui, como as populações estão expostas nas áreas de risco no Brasil e na região centro-oeste."},{"t":"00:38:09","s":"Celene Cunha","x":"É interessante observar aqui"},{"t":"00:38:12","s":"Celene Cunha","x":"A gente está aqui, Goiânia e Brasília, esse eixo Goiânia e Brasília é exatamente uma área mais adensada do nosso estado."},{"t":"00:38:25","s":"Celene Cunha","x":"É um outro estudo que a gente está desenvolvendo desse eixo Goiânia, Anápolis e Brasília, e que contém essas populações..."},{"t":"00:38:36","s":"Celene Cunha","x":"mais expostas."},{"t":"00:38:37","s":"Celene Cunha","x":"Quais são os riscos das cidades?"},{"t":"00:38:40","s":"Celene Cunha","x":"Principalmente, nós trabalhamos no observatório e todos que lidam com o planejamento urbano nas universidades, esse esforço de garantir o direito à cidade."},{"t":"00:38:57","s":"Celene Cunha","x":"E o que a gente percebe?"},{"t":"00:39:00","s":"Celene Cunha","x":"essa fragilização do direito à cidade e a redução da qualidade da vida urbana."},{"t":"00:39:07","s":"Celene Cunha","x":"esse aumento na precariedade habitacional, redução da qualidade dos serviços e do acesso ao saneamento básico e redução da qualidade dos serviços de transporte e acesso à mobilidade urbana."},{"t":"00:39:22","s":"Celene Cunha","x":"Então, aqui, nesse desenho, a gente tem o risco climático, a ameaça climática, a exposição e as vulnerabilidades."},{"t":"00:39:32","s":"Celene Cunha","x":"E é esse o nosso olhar, a nossa preocupação desse projeto, que está sendo, como vocês percebem, faz parte de uma grande rede nacional e a gente segue trabalhando junto, inclusive com situações muito diferenciadas, desde as situações do Sudeste, do Nordeste, e agora, conforme foi bem lembrado aqui,"},{"t":"00:40:01","s":"Celene Cunha","x":"as cidades do Cerrado."},{"t":"00:40:06","s":"Celene Cunha","x":"Nessa etapa, teve um edital, foram selecionadas 50 cidades e vai acontecer um novo edital que nós vamos selecionar, serão selecionadas pelo Ministério das Cidades, daí a gente trabalha com as cidades, mas sem cidades."},{"t":"00:40:24","s":"Celene Cunha","x":"E o que é muito importante, além desse estudo e dessa assessoria técnica que os grupos que fazemos na cidade, é a ideia de uma trilha de aprendizagem."},{"t":"00:40:37","s":"Celene Cunha","x":"Depois vou falar rapidamente."},{"t":"00:40:39","s":"Celene Cunha","x":"Quais são as ações?"},{"t":"00:40:41","s":"Celene Cunha","x":"Fortalecer os instrumentos de planejamento urbano e ordenamento do solo já existentes."},{"t":"00:40:48","s":"Celene Cunha","x":"Naturalmente, quando o Estatuto da Cidade foi promulgado, foi aprovado como fruto de um grande movimento e invejável movimento que ocorreu no Brasil pela reforma"},{"t":"00:41:02","s":"Celene Cunha","x":"e pelo direito à cidade, que culminou no Estatuto da Cidade."},{"t":"00:41:06","s":"Celene Cunha","x":"Naquele momento, o Estatuto da Cidade incorporou a ideia da sustentabilidade urbana, mas alguns desses elementos não foram..."},{"t":"00:41:22","s":"Celene Cunha","x":"discriminados, digamos assim, e não foram aprofundados no sentido de minimizar esses efeitos."},{"t":"00:41:36","s":"Celene Cunha","x":"Quando foi aprovado, ainda não está nessa situação que estamos hoje."},{"t":"00:41:46","s":"Celene Cunha","x":"Nessa seleção de municípios, nesse edital,"},{"t":"00:41:51","s":"Celene Cunha","x":"seis vagas para a região centro-oeste, nós tivemos apenas duas inscrições e dois municípios selecionados, que, no caso nosso, foram municípios de Goiás."},{"t":"00:42:03","s":"Celene Cunha","x":"Mato Grosso não teve nenhum município selecionado, não teve inscrição."},{"t":"00:42:09","s":"Celene Cunha","x":"E os municípios que foram selecionados em Goiás foram os municípios de"},{"t":"00:42:18","s":"Celene Cunha","x":"Goiás e Catalão, cidade de Goiás e Catalão."},{"t":"00:42:22","s":"Celene Cunha","x":"Quais foram os instrumentos elencados, os instrumentos da política urbana que foram definidos nesse edital?"},{"t":"00:42:31","s":"Celene Cunha","x":"Ao se inscrever, o município deveria selecionar até três instrumentos da política urbana que o município considerava importantes para ser trabalhado nesse projeto."},{"t":"00:42:45","s":"Celene Cunha","x":"Esses são os instrumentos existentes, o zoneamento, o macrozoneamento,"},{"t":"00:42:51","s":"Celene Cunha","x":"o parque de vizinhança, parcelamento, o REURB, enfim, todos esses que estão previstos no Estatuto da Cidade e que a maioria dos planos diretores tratam na sua formatação."},{"t":"00:43:11","s":"Celene Cunha","x":"O instrumento mais..."},{"t":"00:43:14","s":"Celene Cunha","x":"Lembrado foi o zoneamento e o macrozoneamento."},{"t":"00:43:17","s":"Celene Cunha","x":"E, na sequência, outros menos lembrados."},{"t":"00:43:23","s":"Celene Cunha","x":"E o que esse projeto busca responder?"},{"t":"00:43:27","s":"Celene Cunha","x":"Responder acrescente à necessidade de articulação entre as agendas urbanas e climáticas, na perspectiva de análise de instrumentos da política urbana, como mediações institucionais."},{"t":"00:43:42","s":"Celene Cunha","x":"Então, é investigar como esses instrumentos podem incorporar a dimensão climática e quais condições influenciam suas possibilidades de aplicação."},{"t":"00:43:53","s":"Celene Cunha","x":"Então é preciso que, nesse cenário, as mudanças climáticas assumam posição central nesse debate."},{"t":"00:44:04","s":"Celene Cunha","x":"Ou seja, que eles precisam ficar disponíveis para mudar o cenário, embora não tenham sido pensados originalmente com essa finalidade,"},{"t":"00:44:13","s":"Celene Cunha","x":"Esse grupo nacional, juntamente com o Ministério das Cidades, tem feito o esforço de decodificar como esses instrumentos existentes podem contribuir para minimizar esses efeitos nas cidades."},{"t":"00:44:35","s":"Celene Cunha","x":"Mas também é preciso, em termos de construção urbana, que esse debate se faça presente com as representações das comunidades tradicionais, dos atingidos, enfim, os que estão mais suscetíveis a esse movimento."},{"t":"00:44:53","s":"Celene Cunha","x":"A ideia, então, é que essa adaptação seja baseada em ecossistemas, no contexto urbano brasileiro,"},{"t":"00:45:03","s":"Celene Cunha","x":"é fundamental que essas ações estejam articuladas ao diagnóstico de risco climático, de modo a garantir a aplicação."},{"t":"00:45:12","s":"Celene Cunha","x":"Um outro aspecto importante é essa fragmentação institucional."},{"t":"00:45:17","s":"Celene Cunha","x":"É muito importante que a implementação haja uma coordenação entre os diferentes setores e as diferentes legislações."},{"t":"00:45:27","s":"Celene Cunha","x":"Esse foi um esforço grande que foi feito nesse projeto."},{"t":"00:45:33","s":"Celene Cunha","x":"Outro aspecto central refere à priorização territorial, que..."},{"t":"00:45:39","s":"Celene Cunha","x":"deve contemplar as populações mais vulneráveis."},{"t":"00:45:47","s":"Celene Cunha","x":"Alguns desafios ainda são importantes, é o monitoramento e avaliação, recomenda-se o fortalecimento do modelo de governança e, principalmente, o enfrentamento do racismo ambiental, que a gente pode..."},{"t":"00:46:05","s":"Celene Cunha","x":"Vamos conversar um pouco depois."},{"t":"00:46:07","s":"Celene Cunha","x":"Aqui é só um exemplo de como estamos articulando, por exemplo, esse instrumento do parcelamento do solo urbano e sua integração com outros instrumentos já existentes."},{"t":"00:46:19","s":"Celene Cunha","x":"Isso aqui é muito importante."},{"t":"00:46:22","s":"Celene Cunha","x":"de ser feita."},{"t":"00:46:23","s":"Celene Cunha","x":"Isso aqui é só um exemplo."},{"t":"00:46:26","s":"Celene Cunha","x":"Essa Lei nº 6.766/1979, que todos que lidam com o planejamento urbano conhecem bem do que ela trata, como ela pode ser trabalhada nessa direção?"},{"t":"00:46:40","s":"Celene Cunha","x":"E quais são as soluções possíveis?"},{"t":"00:46:42","s":"Celene Cunha","x":"Algumas, inclusive, o professor..."},{"t":"00:46:45","s":"Celene Cunha","x":"citou aqui, para a ocupação em conflito com a hidrografia."},{"t":"00:46:51","s":"Celene Cunha","x":"Enfim, quais são as soluções possíveis?"},{"t":"00:46:55","s":"Celene Cunha","x":"E, por último, a Lei da REURB, que selecionei só uma parte dela, que é a regularização fundiária urbana a fim de interesse social."},{"t":"00:47:03","s":"Celene Cunha","x":"Como ela pode ser utilizada?"},{"t":"00:47:06","s":"Celene Cunha","x":"Qual o potencial que ela tem?"},{"t":"00:47:08","s":"Celene Cunha","x":"para minimizar a adaptação climática."},{"t":"00:47:11","s":"Celene Cunha","x":"Aqui são os municípios de Goiás que foram selecionados."},{"t":"00:47:14","s":"Celene Cunha","x":"Acho que a imagem aqui da cidade de Goiás não está muito clara."},{"t":"00:47:19","s":"Celene Cunha","x":"A cidade de Goiás optou pelo instrumento do plano diretor."},{"t":"00:47:23","s":"Celene Cunha","x":"É uma cidade que ainda não tem um plano diretor em vigor."},{"t":"00:47:27","s":"Celene Cunha","x":"O plano diretor da cidade de Goiás é de 1995 ainda."},{"t":"00:47:35","s":"Celene Cunha","x":"E Catalão, que é um município que tem uma estrutura, tem um plano diretor em vigor, tem uma estrutura de gestão municipal muito boa."},{"t":"00:47:45","s":"Celene Cunha","x":"Eles escolheram o parcelamento do solo urbano, o zoneamento e o macrozoneamento."},{"t":"00:47:51","s":"Celene Cunha","x":"Por último, aqui a gente está com esse documento, que eu até trouxe uma cópia, que eu posso deixar com a secretária, que já é resultado, parte do nosso esforço de formação."},{"t":"00:48:06","s":"Celene Cunha","x":"O ano que vem a gente vai ministrar um curso de extensão"},{"t":"00:48:12","s":"Celene Cunha","x":"com a carga horária de 40 horas, dirigida aos gestores municipais."},{"t":"00:48:18","s":"Celene Cunha","x":"Depois vou passar todos os dados para divulgação."},{"t":"00:48:23","s":"Celene Cunha","x":"E, concluindo, acho que já estou a enfrentar as mudanças climáticas."},{"t":"00:48:28","s":"Celene Cunha","x":"Não é apenas uma questão, é social, política e ética."},{"t":"00:48:32","s":"Celene Cunha","x":"é a incorporação do racismo ambiental e deve orientar as decisões, priorizando as populações, e é importante essa integração."},{"t":"00:48:44","s":"Celene Cunha","x":"É isso."},{"t":"00:48:45","s":"Celene Cunha","x":"Muito obrigada."},{"t":"00:48:48","s":"Ary Soares dos Santos","x":"Professora Celene, muito obrigado."},{"t":"00:48:50","s":"Ary Soares dos Santos","x":"Bom, a gente vai vendo aí como que os temas vão dialogando entre si, como que a ciência pura lá da climatologia serve de base para o planejamento urbano e que vai servir de base, esperamos nós, para decisões do poder público de minimizar os efeitos das mudanças climáticas com a sociedade como um todo."},{"t":"00:49:14","s":"Ary Soares dos Santos","x":"Professor João de Deus, é com o senhor."},{"t":"00:49:17","s":"Ary Soares dos Santos","x":"Os próximos 15 minutos."},{"t":"00:49:19","s":"João Batista de Deus","x":"Bom, eu vou tentar ser breve, 15 minutos não dá muito tempo, não, mas, primeiramente, eu quero agradecer ao Pedro, Pedro Novaes, pelo convite."},{"t":"00:49:33","s":"João Batista de Deus","x":"Quero cumprimentar também o professor Carlos pela sua explanação, a professora Celene, que foi minha professora, minha colega, né?"},{"t":"00:49:45","s":"João Batista de Deus","x":"Quero cumprimentar aqui também o Ary."},{"t":"00:49:49","s":"João Batista de Deus","x":"que fomos contemporâneos, estudantes no curso de geografia, tempos bons aqueles."},{"t":"00:50:08","s":"João Batista de Deus","x":"Pedro me perguntou se eu tinha slide."},{"t":"00:50:11","s":"João Batista de Deus","x":"Eu disse que não, que a minha função aqui era ser debatedor."},{"t":"00:50:15","s":"João Batista de Deus","x":"Então eu vou em cima do que foi"},{"t":"00:50:19","s":"João Batista de Deus","x":"Vou, então, fazer..."},{"t":"00:50:20","s":"João Batista de Deus","x":"Fiz aqui as minhas anotações e vou tentar trabalhar."},{"t":"00:50:27","s":"João Batista de Deus","x":"Primeiramente, quero dizer o seguinte."},{"t":"00:50:34","s":"João Batista de Deus","x":"Nós não podemos e não devemos jogar nas costas dos planejadores, dos técnicos das prefeituras, em especial das metrópoles, os problemas da cidade."},{"t":"00:50:48","s":"João Batista de Deus","x":"que não é correto isso."},{"t":"00:50:51","s":"João Batista de Deus","x":"Primeiro, eu odeio quando falam assim, a cidade cresce desordenadamente."},{"t":"00:50:57","s":"João Batista de Deus","x":"Não é verdade."},{"t":"00:50:59","s":"João Batista de Deus","x":"Existe uma ordem implícita na desordem, que é a ordem do mercado."},{"t":"00:51:08","s":"João Batista de Deus","x":"Nós temos que ter claro que o mercado é caótico e ele leva essa desordem para o planejamento."},{"t":"00:51:19","s":"João Batista de Deus","x":"E que o planejamento, ao longo do século XX, ele sofreu inúmeros ataques."},{"t":"00:51:27","s":"João Batista de Deus","x":"Inclusive, pregou-se o fim do planejamento, que deveria ser acabado e só sobrar a gestão."},{"t":"00:51:39","s":"João Batista de Deus","x":"que é o curto prazo."},{"t":"00:51:41","s":"João Batista de Deus","x":"Isso aconteceu, em especial, por influência nos Estados Unidos, quando, no pós-segunda guerra, tentou-se levar para o Estado a perspectiva das empresas, do planejamento empresarial no setor público."},{"t":"00:52:09","s":"João Batista de Deus","x":"E aí entra uma contradição extremamente perversa, porque o setor público não tem que ter lucro."},{"t":"00:52:24","s":"João Batista de Deus","x":"Aí surgiu uma palavra importante que chama o custo-benefício."},{"t":"00:52:35","s":"João Batista de Deus","x":"Eu lembro, no governo Marconi, quando o governo fez uma proposta de criar o metrô de superfície, na época, na Goiás Norte, saía lá do setor, lá do Jardim Curitiba, passava por toda a Goiás Norte, no centro ele ia para o baixo, depois ia na superfície, ia sair lá no Terminal das Bandeiras."},{"t":"00:53:03","s":"João Batista de Deus","x":"Esse projeto foi destroçado na imprensa e pela elite goianiense, porque o custo-benefício era muito alto."},{"t":"00:53:13","s":"João Batista de Deus","x":"Na análise do IBGE, sabe qual era a média de horas que as pessoas do setor noroeste ficavam no ônibus?"},{"t":"00:53:26","s":"João Batista de Deus","x":"era uma hora por dia, meia para ir, meia para voltar, chegando até duas horas, pelo censo do IBGE."},{"t":"00:53:35","s":"João Batista de Deus","x":"Agora, perder uma hora por dia para uma pessoa, o custo disso na vida dela é muito alto."},{"t":"00:53:45","s":"João Batista de Deus","x":"Agora, para aquele que estava lá, que anda no seu carro, não é muito alto."},{"t":"00:53:52","s":"João Batista de Deus","x":"E aí entra uma outra coisa,"},{"t":"00:53:54","s":"João Batista de Deus","x":"que a cidade... Vou chegar onde o professor Carlos colocou."},{"t":"00:53:59","s":"João Batista de Deus","x":"A cidade é uma construção cultural."},{"t":"00:54:10","s":"João Batista de Deus","x":"Ela é uma construção cultural."},{"t":"00:54:13","s":"João Batista de Deus","x":"E ela é a espacialização, a materialização da nossa sociedade."},{"t":"00:54:19","s":"João Batista de Deus","x":"Aí eu fico pensando, quando o cara estava falando sobre o clima, as ilhas de calor."},{"t":"00:54:27","s":"João Batista de Deus","x":"Quando um corpo anda, se locomove, se ele pesa 80 quilos, ele tem que gastar energia para poder mover 80 quilos."},{"t":"00:54:44","s":"João Batista de Deus","x":"Ao fazer isso, ele vai emitir calor."},{"t":"00:54:48","s":"João Batista de Deus","x":"Os nossos carros são muito grandes, três toneladas."},{"t":"00:54:53","s":"João Batista de Deus","x":"E olha quantos carros nós temos na cidade emitindo calor o tempo inteiro."},{"t":"00:54:59","s":"João Batista de Deus","x":"Imaginem isso, não é, Carlos?"},{"t":"00:55:02","s":"João Batista de Deus","x":"Pensa bem."},{"t":"00:55:03","s":"João Batista de Deus","x":"E nós criamos as nossas cidades baseado no modelo estadunidense dos subúrbios."},{"t":"00:55:14","s":"João Batista de Deus","x":"onde as pessoas têm que deslocar muitos quilômetros para poder comprar no supermercado, para poder ir para o trabalho, morar nos condomínios."},{"t":"00:55:25","s":"João Batista de Deus","x":"E aí, veja como é perverso."},{"t":"00:55:30","s":"João Batista de Deus","x":"E aí você vende a tranquilidade."},{"t":"00:55:33","s":"João Batista de Deus","x":"A tranquilidade passou a ser mercadoria."},{"t":"00:55:37","s":"João Batista de Deus","x":"Vá morar num lugar tranquilo."},{"t":"00:55:41","s":"João Batista de Deus","x":"Só que o impacto ambiental disso, naquilo que o Carlos colocou, é muito alto."},{"t":"00:55:48","s":"João Batista de Deus","x":"E vende, inclusive, a natureza."},{"t":"00:55:51","s":"João Batista de Deus","x":"Vá morar de frente ao parque."},{"t":"00:55:54","s":"João Batista de Deus","x":"Você criou o imaginário, porque, na verdade, o parque é urbanizado, não tem nada de natural ali."},{"t":"00:56:01","s":"João Batista de Deus","x":"Ele é urbanizado, ele é feito para a gente, porque a cidade é o nosso ambiente de vida."},{"t":"00:56:08","s":"João Batista de Deus","x":"Tem que ser feito para a gente."},{"t":"00:56:10","s":"João Batista de Deus","x":"para nós, seres humanos."},{"t":"00:56:14","s":"João Batista de Deus","x":"E tudo vira mercadoria."},{"t":"00:56:17","s":"João Batista de Deus","x":"Vá morar de frente ao parque, vá morar de frente à natureza."},{"t":"00:56:25","s":"João Batista de Deus","x":"E, depois, quando você cria os problemas, aí coloca a culpa na prefeitura, nos técnicos da prefeitura, que a cidade cresce desordenadamente."},{"t":"00:56:41","s":"João Batista de Deus","x":"E olha o que o Carlos mostrou aqui, os problemas que são criados culturalmente."},{"t":"00:56:57","s":"João Batista de Deus","x":"Na sexta-feira, a minha enteada, que morava fora do Brasil, ela trabalhava fora, voltou,"},{"t":"00:57:07","s":"João Batista de Deus","x":"E aí eles compraram um apartamento em Goiânia."},{"t":"00:57:12","s":"João Batista de Deus","x":"E aí ela foi lá, tinha lá, ela foi saber como é que fazia para poder separar o lixo."},{"t":"00:57:19","s":"João Batista de Deus","x":"Aí eles disseram assim, não, aqui ninguém separa lixo, não."},{"t":"00:57:23","s":"João Batista de Deus","x":"Os prédios aqui ninguém separa."},{"t":"00:57:25","s":"João Batista de Deus","x":"Eu não posso brigar porque não tem uma lei que obriga a separar o lixo."},{"t":"00:57:30","s":"João Batista de Deus","x":"Tem lei."},{"t":"00:57:31","s":"João Batista de Deus","x":"Ninguém separa lixo."},{"t":"00:57:33","s":"João Batista de Deus","x":"Os prédios da classe média alta não separam lixo."},{"t":"00:57:37","s":"João Batista de Deus","x":"Gente, eu cresci numa casa, separando o lixo que foi na minha casa, separando o lixo."},{"t":"00:57:44","s":"João Batista de Deus","x":"Agora, a classe média alta, não."},{"t":"00:57:47","s":"João Batista de Deus","x":"Ela não separa lixo."},{"t":"00:57:50","s":"João Batista de Deus","x":"E qual o impacto disso?"},{"t":"00:57:52","s":"João Batista de Deus","x":"É o aumento dos resíduos sólidos."},{"t":"00:57:58","s":"João Batista de Deus","x":"Você tem que gastar para poder aterrar esse lixo, porque não tem uma lei no município, porque não obriga as pessoas a reciclar e elas não têm consciência que devem reciclar."},{"t":"00:58:15","s":"João Batista de Deus","x":"E esses problemas que o Carlos..."},{"t":"00:58:17","s":"João Batista de Deus","x":"Quantos problemas que tem de lixo na rua que não impactam nas enchentes?"},{"t":"00:58:26","s":"João Batista de Deus","x":"Sabe o que me encabula?"},{"t":"00:58:28","s":"João Batista de Deus","x":"Você vai marcando para mim."},{"t":"00:58:30","s":"João Batista de Deus","x":"Eu participei das audiências públicas do plano diretor."},{"t":"00:58:38","s":"João Batista de Deus","x":"Eu briguei muito porque o pessoal diminuiu a APP em Goiânia."},{"t":"00:58:47","s":"João Batista de Deus","x":"Eu achei aquilo um crime."},{"t":"00:58:49","s":"João Batista de Deus","x":"Primeiro, porque você cria áreas mais vulneráveis às máximas climáticas que a cidade pode ter."},{"t":"00:59:03","s":"João Batista de Deus","x":"Primeira coisa."},{"t":"00:59:04","s":"João Batista de Deus","x":"Segundo, porque você diminui as áreas de vegetação, impactando no microclima."},{"t":"00:59:13","s":"João Batista de Deus","x":"E você poderia criar parques lineares na cidade, incorporando aquela área para a população."},{"t":"00:59:22","s":"João Batista de Deus","x":"E aí eu vi nessa audiência pública um empresário que chegou lá e falou assim, não, que tinha que diminuir a APP porque ele tinha vendido, ele tinha feito um empreendimento e tinha vendido o lote e não conseguia legalizar porque estava na APP."},{"t":"00:59:41","s":"João Batista de Deus","x":"E eu tive a capacidade de assistir a advogada da CIEG ir lá falar que tinha que diminuir a APP porque o empresário construía e a prefeitura ia lá embargar e ele tinha que demolir porque estava dentro da APP."},{"t":"01:00:03","s":"João Batista de Deus","x":"Gente, eu fiquei pensando, como é que pode?"},{"t":"01:00:07","s":"João Batista de Deus","x":"Olha a elite que nós temos."},{"t":"01:00:13","s":"João Batista de Deus","x":"Vocês estão entendendo o problema que nós enfrentamos?"},{"t":"01:00:19","s":"João Batista de Deus","x":"E aí depois coloca a culpa nos técnicos da prefeitura, que são os culpados."},{"t":"01:00:28","s":"João Batista de Deus","x":"Então, eu quero dizer que a cidade é uma estrutura cultural, ela é a materialização do que nós somos."},{"t":"01:00:42","s":"João Batista de Deus","x":"dentro das nossas virtudes e das nossas perversidades."},{"t":"01:00:47","s":"João Batista de Deus","x":"Infelizmente, ou felizmente, é isso."},{"t":"01:00:52","s":"João Batista de Deus","x":"E nós temos que olhar a cidade nesse viés, para pensar a cidade para os seres humanos, que aqui é onde nós vivemos."},{"t":"01:01:08","s":"João Batista de Deus","x":"E nós temos que pensar o meio ambiente urbano enquanto algo para que possamos viver bem, para que os seres humanos aqui possam viver bem."},{"t":"01:01:23","s":"João Batista de Deus","x":"E, para isso, nós temos que entender aquilo que o professor Carlos muito bem explicou aqui, como é que a natureza age"},{"t":"01:01:34","s":"João Batista de Deus","x":"dentro do ambiente que nós construímos."},{"t":"01:01:40","s":"João Batista de Deus","x":"Essa é a nossa realidade."},{"t":"01:01:43","s":"João Batista de Deus","x":"Temos que pensar nessa perspectiva."},{"t":"01:01:46","s":"João Batista de Deus","x":"Como é que nós vamos pensar, já estou concluindo, pensar numa cidade amigável para nós, seres humanos, de uma forma geral,"},{"t":"01:02:01","s":"João Batista de Deus","x":"Não só para uma pequena parcela que vai lá viver isolada do restante da cidade."},{"t":"01:02:11","s":"João Batista de Deus","x":"Dentro dos muros, se autosegregar."},{"t":"01:02:15","s":"João Batista de Deus","x":"Mas numa cidade para todos."},{"t":"01:02:18","s":"João Batista de Deus","x":"É isso."},{"t":"01:02:19","s":"João Batista de Deus","x":"Obrigado."},{"t":"01:02:25","s":"Ary Soares dos Santos","x":"Professor João de Deus, muito obrigado."},{"t":"01:02:27","s":"Ary Soares dos Santos","x":"Bom, gente, vocês estiveram aqui."},{"t":"01:02:29","s":"Ary Soares dos Santos","x":"uma pequena amostra do porquê da nossa paixão pela geografia."},{"t":"01:02:34","s":"Ary Soares dos Santos","x":"São três visões distintas, desde a área física da geografia, passando pelo planejamento e passando por essa visão, digamos, até marxista de se pensar a relação da sociedade com a cidade."},{"t":"01:02:53","s":"Ary Soares dos Santos","x":"E eu gostaria de sugerir para vocês que acessassem o relatório do primeiro Goiânia Resiliente."},{"t":"01:03:02","s":"Ary Soares dos Santos","x":"Ele fala lá na sua seção 4, na página 23, que o mesmo clima atinge Goiânia de forma desigual."},{"t":"01:03:12","s":"Ary Soares dos Santos","x":"E eu tive a oportunidade..."},{"t":"01:03:14","s":"Ary Soares dos Santos","x":"de falar com o prefeito Sandro Mabel, ainda antes dele tomar posse, ainda no calor da campanha, para o senhor Sandro, observa bem o que acontece com a cidade."},{"t":"01:03:25","s":"Ary Soares dos Santos","x":"Porque a enxurrada que atrapalha o meu carro de transitar na parte alta da cidade..."},{"t":"01:03:31","s":"Ary Soares dos Santos","x":"me causando um prejuízo temporal, pontual, é a mesma enxurrada que vai provocar enchente na periferia da cidade."},{"t":"01:03:40","s":"Ary Soares dos Santos","x":"Então, o prejuízo é muito diferente, como diz aqui o João de Deus, a professora Celene colocou, o professor Carlos Gurjão, aquilo que afeta..."},{"t":"01:03:52","s":"Ary Soares dos Santos","x":"A sociedade que está mais bem estabelecida, que teve ambientes melhores de sobrevivência, afeta diferente aqueles que mais dependem do poder público, que são as periferias da cidade."},{"t":"01:04:08","s":"Ary Soares dos Santos","x":"Porque aquilo que atrapalha o nosso cotidiano"},{"t":"01:04:11","s":"Ary Soares dos Santos","x":"é a mesma chuva, é a mesma água que vai acabar com o patrimônio, talvez de gerações, na periferia da cidade."},{"t":"01:04:19","s":"Ary Soares dos Santos","x":"Então, a responsabilidade nossa de pensar a cidade"},{"t":"01:04:24","s":"Ary Soares dos Santos","x":"ela é cada dia mais exigente."},{"t":"01:04:28","s":"Ary Soares dos Santos","x":"E, por isso, a importância de um fórum deste."},{"t":"01:04:31","s":"Ary Soares dos Santos","x":"Como o João de Deus antecipou o seu tempo, fica aí um minuto para cada um fazer a sua fala final."},{"t":"01:04:38","s":"Ary Soares dos Santos","x":"Infelizmente, a gente não tem como abrir para vocês contribuírem na construção deste debate, até pelo estabelecimento dos tempos e de outras mesas que a gente vai ter no decorrer."},{"t":"01:04:51","s":"Ary Soares dos Santos","x":"Fique à vontade."},{"t":"01:04:58","s":"Celene Cunha","x":"Bom, gente, eu queria fazer uma sugestão a partir do que o Carlos falou, do que o João falou."},{"t":"01:05:14","s":"Celene Cunha","x":"e até das reflexões que a gente tem feito nesses estudos últimos e recentes."},{"t":"01:05:21","s":"Celene Cunha","x":"Eu tive a oportunidade, juntamente com o professor João de Deus, de trabalharmos num projeto grande do governo do Estado, no PDUI da região metropolitana, o Plano de Desenvolvimento Urbano da região metropolitana."},{"t":"01:05:42","s":"Celene Cunha","x":"Ele foi elaborado no âmbito da UFG, na equipe técnica da UFG, com parceria com a FUNAPE."},{"t":"01:05:51","s":"Celene Cunha","x":"E chegamos na fase final, ele foi abortado."},{"t":"01:05:59","s":"Celene Cunha","x":"Nós terminamos, existe uma minuta do plano já divulgada,"},{"t":"01:06:05","s":"Celene Cunha","x":"e foi abortado."},{"t":"01:06:07","s":"Celene Cunha","x":"Não foi a termo, é uma competência do governo do Estado aprovar e deliberar e criar os mecanismos para a gestão desse plano."},{"t":"01:06:18","s":"Celene Cunha","x":"Ele deve ser aprovado pela Assembleia Legislativa."},{"t":"01:06:23","s":"Celene Cunha","x":"Bom, sempre que posso, faço referência a isso, que ainda está paralisado esse estudo."},{"t":"01:06:33","s":"Celene Cunha","x":"Mas o que eu queria sugerir, e nesse plano, uma das estratégias territoriais que a gente propõe é a preservação da região norte."},{"t":"01:06:46","s":"Celene Cunha","x":"da região metropolitana, região norte de Goiânia, região norte da região metropolitana, porque é exatamente a nossa área com maior densidade hídrica"},{"t":"01:06:59","s":"Celene Cunha","x":"e de vegetação ainda existentes."},{"t":"01:07:02","s":"Celene Cunha","x":"Essa parte da região metropolitana de Goiânia é a parte da floresta estacional, não é exatamente cerrado, são as manchas do chamado Mato Grosso Goiano que ainda sobrevivem nessa parte."},{"t":"01:07:18","s":"Celene Cunha","x":"Bom, qual é o diálogo que a gente pode fazer dessa sugestão feita nesse plano metropolitano"},{"t":"01:07:27","s":"Celene Cunha","x":"com o Plano Diretor de Goiânia atual, que foi aprovado, recente."},{"t":"01:07:31","s":"Celene Cunha","x":"Essa é uma coisa que eu gostaria de fazer esse desafio."},{"t":"01:07:35","s":"Celene Cunha","x":"O Plano Diretor, na sua Lei de Uso do Solo de Expansão Urbana, liberou... Acho que vocês que atuam na prefeitura sabem, na gestão municipal, a própria Ama sabe disso, mas seria muito importante focar..."},{"t":"01:07:55","s":"Celene Cunha","x":"nesse plano diretor que foi aprovado, o que está sendo feito e que já está em curso pelo capital imobiliário de Goiânia, que já está ocupando essa região com vários empreendimentos."},{"t":"01:08:15","s":"Celene Cunha","x":"E o impacto disso, professor Nu..."},{"t":"01:08:19","s":"Celene Cunha","x":"no clima regional, não só Goiânia, no clima regional, todas as cidades que compõem essa região metropolitana, o papel que essa área norte da região metropolitana e de Goiânia tem como manancial para água de beber, simplesmente."},{"t":"01:08:37","s":"Celene Cunha","x":"para a água, para o consumo humano, o quanto é importante essa preservação."},{"t":"01:08:43","s":"Celene Cunha","x":"Eu queria deixar esse alerta."},{"t":"01:08:49","s":"Celene Cunha","x":"Esse plano diretor aprovado não dialogou com os resultados do plano metropolitano."},{"t":"01:08:56","s":"Celene Cunha","x":"Nós fizemos um esforço grande para estar presente em todas as audiências, contribuir com o debate"},{"t":"01:09:04","s":"Celene Cunha","x":"para trazer esse resultado dessa pesquisa realizada no âmbito da UFG e que a gente chegou a essa sugestão de estratégia."},{"t":"01:09:14","s":"Celene Cunha","x":"Então, eu deixo aqui essa preocupação."},{"t":"01:09:18","s":"Celene Cunha","x":"porque é a área do estado de Goiás, junto com a região do entorno de Brasília, que contém o maior número de população do nosso estado."},{"t":"01:09:30","s":"Celene Cunha","x":"80% da população de Goiás, mais de 80% vive na região metropolitana de Goiás e região metropolitana de Brasília, nesse entorno de Brasília."},{"t":"01:09:39","s":"Celene Cunha","x":"Então, é isso."},{"t":"01:09:40","s":"Celene Cunha","x":"Eu não podia deixar de falar sobre isso."},{"t":"01:09:44","s":"Ary Soares dos Santos","x":"Obrigada."},{"t":"01:09:44","s":"Ary Soares dos Santos","x":"Rapidamente, professor, quem encerrar?"},{"t":"01:09:46","s":"Ary Soares dos Santos","x":"Alguma coisa a mais?"},{"t":"01:09:47","s":"Ary Soares dos Santos","x":"João?"},{"t":"01:09:50","s":"João Batista de Deus","x":"Gente, só muito breve."},{"t":"01:09:52","s":"João Batista de Deus","x":"Nós corremos o risco, no futuro, de não ter água para todos aqui na região metropolitana."},{"t":"01:10:00","s":"João Batista de Deus","x":"Nosso estudo mostrou isso."},{"t":"01:10:03","s":"João Batista de Deus","x":"Agora, o futuro é futuro."},{"t":"01:10:06","s":"João Batista de Deus","x":"Ninguém pensa no futuro, mas nós, como professores, como gestores, temos que pensar no futuro."},{"t":"01:10:16","s":"Ary Soares dos Santos","x":"Gente, muito obrigado a vocês."},{"t":"01:10:18","s":"Ary Soares dos Santos","x":"Desculpem a gente por não abrir aqui as contribuições da plenária, mas o tempo é exíguo."},{"t":"01:10:26","s":"Ary Soares dos Santos","x":"E, como comecei falando em mídias sociais, a gente tem que fazer aqui a nossa selfie, não é, professora?"},{"t":"01:10:32","s":"Ary Soares dos Santos","x":"Professora, por favor, aqui uma selfie para posteridade."},{"t":"01:10:39","s":"João Batista de Deus","x":"A selfie do painel."},{"t":"01:10:49","s":"Ary Soares dos Santos","x":"Isso, gente, muitíssimo obrigado."},{"t":"01:10:51","s":"Ary Soares dos Santos","x":"Pedro, muitíssimo obrigado."},{"t":"01:10:52","s":"Ary Soares dos Santos","x":"Desculpa aí de ter estendido o tempo um pouco."},{"t":"01:10:54","s":"Pedro Novaes","x":"Obrigado, Ary, obrigado, Celene, obrigado, João, obrigado, Carlos."},{"t":"01:10:59","s":"Pedro Novaes","x":"A gente vai seguir sem intervalo, gente, pelo adiantado da hora, mas tem um cafezinho lá fora, tem água, quem quiser sair para tomar um café."},{"t":"01:11:09","s":"Pedro Novaes","x":"E a gente segue agora com esse outro painel."}]};
